ga0h(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u062f\u0646"},
ga0V(){return"\u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc"},
ga1W(){return"\u06af\u06d5\u0695\u0627\u0646\u062f\u0646\u06d5\u0648\u06d5"},
ga0l(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u0627\u0648"},
