ga25(){return"\u0642\u06c6\u0646\u0627\u063a \u06af\u06d5\u0695\u06ce\u0646\u062f\u0631\u0627\u06cc\u06d5\u0648\u06d5."},
ga16(){return" \xb7 \u0648\u06d5\u0631\u06af\u0631\u062a\u0646"},
ga14(){return" \xb7 \u06a9\u06c6\u062a\u0627\u06cc\u06cc"},
ga15(){return"\u0626\u06d5\u0645\u06d5 \u0642\u06c6\u0646\u0627\u063a\u06cc \u06a9\u06c6\u062a\u0627\u06cc\u06cc\u06d5: \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0628\u06af\u0648\u0627\u0632\u0631\u06ce\u062a\u06d5\u0648\u06d5 \u0628\u06c6 \u0626\u06ce\u0631\u06d5 \u0648\u06d5\u06a9 \u0646\u06ce\u0631\u062f\u0631\u0627\u0648 \u0626\u06d5\u0698\u0645\u0627\u0631 \u062f\u06d5\u06a9\u0631\u06ce\u062a \u0648 \u0686\u06cc\u062a\u0631 \u0686\u0627\u0644\u0627\u06a9 \u0646\u06cc\u06cc\u06d5. \u0648\u06d5\u06a9 \u0642\u06c6\u0646\u0627\u063a\u06cc \u06af\u06d5\u06cc\u0627\u0646\u062f\u0646 \u0628\u06cc\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5. \u0628\u06c6 \u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u0647\u06d5\u0646\u06af\u0627\u0648\u06ce\u06a9\u06cc \u062a\u0631\u060c \u0642\u06c6\u0646\u0627\u063a\u06ce\u06a9\u06cc \u0646\u0648\u06ce \u0632\u06cc\u0627\u062f \u0628\u06a9\u06d5 \u0644\u06d5 \u062c\u06cc\u0627\u062a\u06cc \u06af\u06c6\u0695\u06cc\u0646\u06cc \u0646\u0627\u0648\u06cc \u0626\u06d5\u0645 \u0642\u06c6\u0646\u0627\u063a\u06d5."},
ga1H(){return"\u0628\u06c6 \u067e\u06ce\u0634\u06d5\u0648\u06d5 \u0628\u06af\u0648\u0627\u0632\u06d5\u0631\u06d5\u0648\u06d5"},
ga1G(){return"\u0628\u06c6 \u062f\u0648\u0627\u0648\u06d5 \u0628\u06af\u0648\u0627\u0632\u06d5\u0631\u06d5\u0648\u06d5"},
gHK(){return"\u0628\u06cc\u0628\u06d5 \u0633\u06d5\u0631\u06d5\u0648\u06d5 (\u0644\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u06a9\u06d5\u06cc\u0633 \u067e\u06ce\u0634\u062a\u0631 \u062f\u06d5\u0631\u062f\u06d5\u06a9\u06d5\u0648\u06ce\u062a)"},
gHJ(){return"\u0628\u06cc\u0628\u06d5 \u062e\u0648\u0627\u0631\u06d5\u0648\u06d5"},
