gaiU(){return"\u067e\u06d5\u06cc\u06a4\u06d5\u06a9\u0627 \u0646\u0647\u06ce\u0646\u06cc \u06cc\u0627 \u0646\u0648\u06cc \u0628\u06c6 \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u062e\u06c6 \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5."},
gaiS(){return"\u067e\u06d5\u06cc\u06a4\u0627 \u0646\u0647\u06ce\u0646\u06cc \u06cc\u0627 \u0646\u0648\u06cc"},
